CREATE SCHEMA auth;
CREATE TYPE public.app_role AS ENUM ('super_admin');
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT '00000000-0000-0000-0000-000000000001'::uuid $$;
CREATE FUNCTION public.has_role(uuid,public.app_role) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION public.get_my_company_id() RETURNS uuid LANGUAGE sql AS $$ SELECT '00000000-0000-0000-0000-000000000001'::uuid $$;
CREATE FUNCTION public._cg_assert_enabled(uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN END $$;
CREATE TABLE public.scadenze(id uuid,company_id uuid,direction text,status text,description text,amount numeric,paid_amount numeric,due_date date,supplier_id uuid,contact_id uuid);
CREATE TABLE public.suppliers(id uuid,name text);
CREATE TABLE public.marketing_contacts(id uuid,company_name text,first_name text,last_name text);
CREATE TABLE public.orders(id uuid,company_id uuid,current_status_id uuid,status text,fulfillment_status text,deleted_at timestamptz,created_at timestamptz,percentuale_avanzamento numeric);
CREATE TABLE public.order_statuses(id uuid,company_id uuid,position int,is_support_phase boolean);
CREATE TABLE public.order_installments(order_id uuid,is_paid boolean,amount numeric);
CREATE TABLE public.v_ordine_marginalita(id uuid,company_id uuid,order_code text,description text,cliente_nome text,work_start_date date,work_end_date date,preventivo_contratto numeric,preventivo_totale numeric,consuntivo numeric,costo_acquisti numeric,costo_errori numeric,variazioni_approvate numeric,margine numeric,margine_perc numeric);
CREATE TABLE public.v_cg_ricavi_classificati(company_id uuid,anno int,mese int,importo_imponibile numeric);
CREATE TABLE public.v_cg_costi_classificati(company_id uuid,anno int,mese int,macro_voce text,importo numeric);
CREATE TABLE public.ce_riclassificato_overrides(company_id uuid,esercizio int,mese int,voce_chiave text,importo_override numeric);
CREATE TABLE public.cg_classificazione_voci(company_id uuid,voce_chiave text,macro_voce text,is_active boolean);
CREATE TABLE public.cedolini(company_id uuid,anno int,mese int,stato text,lordo numeric,contributi_datore numeric);
CREATE TABLE public.cespiti(company_id uuid,is_active boolean,data_acquisto date,data_dismissione date,aliquota_amm numeric,costo_storico numeric,vita_utile_mesi int);
CREATE TABLE public.cg_aliquote_imposte(company_id uuid,ires_pct numeric,irap_pct numeric,addizionale_ires_pct numeric,base_irap_include_personale boolean);
CREATE TABLE public.company_costs(company_id uuid,paid_date date,due_date date,category text);
CREATE TABLE public.cg_loans(company_id uuid,is_active boolean,rata_mensile numeric,capitale_residuo numeric,tasso_pct numeric);
CREATE TABLE public.invoices(company_id uuid,issue_date date,status text);
CREATE TABLE public.patrimonio_netto(company_id uuid,esercizio int,capitale_sociale numeric,riserva_legale numeric,riserva_straordinaria numeric,altre_riserve numeric);
CREATE TABLE public.test_sp(data jsonb);
INSERT INTO test_sp VALUES ('{"attivo":{"attivo_circolante":1000,"totale":1500},"passivo":{"pas_corrente":100,"mezzi_propri":800,"totale":1400},"quadratura":{"differenza":100,"quadrato":false}}');
CREATE FUNCTION public.cg_get_stato_patrimoniale_riclassificato(uuid,int) RETURNS jsonb LANGUAGE sql AS $$ SELECT data FROM public.test_sp $$;
CREATE FUNCTION public.cg_get_pfn(uuid,int) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
